  const LogoC = monochrome ? FortanixLogoImageMono : FortanixLogoImage;
  return (
    <figure
      {...propsRest}
      className={cx(
        cl['bk-fortanix-armor-logo'],
        { [cl['bk-fortanix-armor-logo--stacked']]: stacked },
