          <div className={cx(cl['bk-public-layout__product-info__cards'])}>
            {productInfoCards}
          </div>
        </div>
      </div>
    );
  },
  {
    FortanixLogo,
    FortanixArmorLogo,
    Heading,
    ProductInfoCard,
  },
);

