  const removeFilter = (index: number) => {
    const newFilters = filters.filter((_, i) => i !== index);
    query?.(newFilters);
  };

  const removeAllFilters = () => {
    query?.([]);
  };

  return {
    filters,
    setFilters,
    addFilter,
    removeFilter,
    removeAllFilters,
  };
};

